namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    [Fact]
    public void Constructor_SetsPageIndexAndTotalPages()
    {
        // Arrange
        var items = new List<string> { "a", "b", "c" };

        // Act
        var list = new PaginatedList<string>(items, 10, 2, 3);

        // Assert
        Assert.Equal(2, list.PageIndex);
        Assert.Equal(4, list.TotalPages); // ceil(10/3) = 4
        Assert.Equal(3, list.Count);
        Assert.Contains("a", list);
        Assert.Contains("b", list);
        Assert.Contains("c", list);
    }

    [Theory]
    [InlineData(10, 5, 2)]  // ceil(10/5) = 2
    [InlineData(11, 5, 3)]  // ceil(11/5) = 3
    [InlineData(1, 5, 1)]   // ceil(1/5) = 1
    [InlineData(0, 5, 0)]   // ceil(0/5) = 0
    [InlineData(5, 5, 1)]   // ceil(5/5) = 1
    public void TotalPages_CalculatesCorrectly(int count, int pageSize, int expectedTotalPages)
    {
        var list = new PaginatedList<int>(new List<int>(), count, 1, pageSize);
        Assert.Equal(expectedTotalPages, list.TotalPages);
    }

    [Fact]
    public void HasPreviousPage_WhenPageIndexIsOne_ReturnsFalse()
    {
        var list = new PaginatedList<int>(new List<int>(), 10, 1, 5);
        Assert.False(list.HasPreviousPage);
    }

    [Fact]
    public void HasPreviousPage_WhenPageIndexIsGreaterThanOne_ReturnsTrue()
    {
        var list = new PaginatedList<int>(new List<int>(), 10, 2, 5);
        Assert.True(list.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_WhenOnLastPage_ReturnsFalse()
    {
        var list = new PaginatedList<int>(new List<int>(), 10, 2, 5); // totalPages=2, page=2
        Assert.False(list.HasNextPage);
    }

    [Fact]
    public void HasNextPage_WhenNotOnLastPage_ReturnsTrue()
    {
        var list = new PaginatedList<int>(new List<int>(), 10, 1, 5); // totalPages=2, page=1
        Assert.True(list.HasNextPage);
    }

    [Fact]
    public void Create_WithQueryable_ReturnsCorrectPage()
    {
        // Arrange
        var source = Enumerable.Range(1, 20).AsQueryable();

        // Act
        var page1 = PaginatedList<int>.Create(source, 1, 5);

        // Assert
        Assert.Equal(1, page1.PageIndex);
        Assert.Equal(4, page1.TotalPages); // ceil(20/5)
        Assert.Equal(5, page1.Count);
        Assert.Equal(new[] { 1, 2, 3, 4, 5 }, page1.ToArray());
        Assert.True(page1.HasNextPage);
        Assert.False(page1.HasPreviousPage);
    }

    [Fact]
    public void Create_SecondPage_SkipsFirstPageItems()
    {
        var source = Enumerable.Range(1, 20).AsQueryable();

        var page2 = PaginatedList<int>.Create(source, 2, 5);

        Assert.Equal(2, page2.PageIndex);
        Assert.Equal(new[] { 6, 7, 8, 9, 10 }, page2.ToArray());
        Assert.True(page2.HasPreviousPage);
        Assert.True(page2.HasNextPage);
    }

    [Fact]
    public void Create_LastPage_HasNoNextPage()
    {
        var source = Enumerable.Range(1, 20).AsQueryable();

        var page4 = PaginatedList<int>.Create(source, 4, 5);

        Assert.Equal(4, page4.PageIndex);
        Assert.Equal(new[] { 16, 17, 18, 19, 20 }, page4.ToArray());
        Assert.True(page4.HasPreviousPage);
        Assert.False(page4.HasNextPage);
    }

    [Fact]
    public void Create_PartialLastPage_ContainsRemainingItems()
    {
        var source = Enumerable.Range(1, 7).AsQueryable();

        var page2 = PaginatedList<int>.Create(source, 2, 5);

        Assert.Equal(2, page2.PageIndex);
        Assert.Equal(2, page2.TotalPages);
        Assert.Equal(new[] { 6, 7 }, page2.ToArray());
        Assert.False(page2.HasNextPage);
    }

    [Fact]
    public void Create_EmptySource_ReturnsEmptyList()
    {
        var source = Enumerable.Empty<int>().AsQueryable();

        var page = PaginatedList<int>.Create(source, 1, 5);

        Assert.Empty(page);
        Assert.Equal(0, page.TotalPages);
        Assert.False(page.HasPreviousPage);
        Assert.False(page.HasNextPage);
    }

    [Fact]
    public void Create_SingleItem_OnePage()
    {
        var source = new[] { 42 }.AsQueryable();

        var page = PaginatedList<int>.Create(source, 1, 10);

        Assert.Single(page);
        Assert.Equal(42, page[0]);
        Assert.Equal(1, page.TotalPages);
        Assert.False(page.HasPreviousPage);
        Assert.False(page.HasNextPage);
    }
}

