        Assert.Equal(new[] { 6, 7, 8, 9, 10 }, page2.ToArray());
        Assert.True(page2.HasPreviousPage);
        Assert.True(page2.HasNextPage);
    }

    [Fact]
    public void Create_LastPage_HasNoNextPage()
    {
        var source = Enumerable.Range(1, 20).AsQueryable();

        var page4 = PaginatedList<int>.Create(source, 4, 5);

        Assert.Equal(4, page4.PageIndex);
        Assert.Equal(new[] { 16, 17, 18, 19, 20 }, page4.ToArray());
        Assert.True(page4.HasPreviousPage);
        Assert.False(page4.HasNextPage);
    }

    [Fact]
    public void Create_PartialLastPage_ContainsRemainingItems()
    {
        var source = Enumerable.Range(1, 7).AsQueryable();

        var page2 = PaginatedList<int>.Create(source, 2, 5);

        Assert.Equal(2, page2.PageIndex);
        Assert.Equal(2, page2.TotalPages);
        Assert.Equal(new[] { 6, 7 }, page2.ToArray());
        Assert.False(page2.HasNextPage);
    }

    [Fact]
    public void Create_EmptySource_ReturnsEmptyList()
    {
        var source = Enumerable.Empty<int>().AsQueryable();

        var page = PaginatedList<int>.Create(source, 1, 5);

        Assert.Empty(page);
        Assert.Equal(0, page.TotalPages);
        Assert.False(page.HasPreviousPage);
        Assert.False(page.HasNextPage);
    }

    [Fact]
    public void Create_SingleItem_OnePage()
    {
        var source = new[] { 42 }.AsQueryable();

        var page = PaginatedList<int>.Create(source, 1, 10);

        Assert.Single(page);
        Assert.Equal(42, page[0]);
        Assert.Equal(1, page.TotalPages);
        Assert.False(page.HasPreviousPage);
        Assert.False(page.HasNextPage);
    }
