using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new StudentsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Student CreateStudent(string firstName = "John", string lastName = "Doe", DateTime? enrollDate = null)
    {
        var student = new Student
        {
            FirstMidName = firstName,
            LastName = lastName,
            EnrollmentDate = enrollDate ?? new DateTime(2020, 9, 1)
        };
        _context.Students.Add(student);
        _context.SaveChanges();
        return student;
    }

    #region Index

    [Fact]
    public void Index_NoParams_ReturnsViewWithStudents()
    {
        // Arrange
        CreateStudent("Alice", "Smith");
        CreateStudent("Bob", "Jones");

        // Act
        var result = _controller.Index(null, null, null, null);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal(2, model.Count);
    }

    [Fact]
    public void Index_WithSearchString_FiltersStudentsByLastName()
    {
        // Arrange
        CreateStudent("Alice", "Smith");
        CreateStudent("Bob", "Jones");

        // Act
        var result = _controller.Index(null, null, "Smith", null);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Single(model);
        Assert.Equal("Smith", model[0].LastName);
    }

    [Fact]
    public void Index_WithSearchString_FiltersStudentsByFirstName()
    {
        CreateStudent("Alice", "Smith");
        CreateStudent("Bob", "Jones");

        var result = _controller.Index(null, null, "Alice", null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Single(model);
        Assert.Equal("Alice", model[0].FirstMidName);
    }

    [Fact]
    public void Index_SortByNameDesc_ReturnsDescendingOrder()
    {
        CreateStudent("Alice", "Alpha");
        CreateStudent("Bob", "Zeta");

        var result = _controller.Index("name_desc", null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal("Zeta", model[0].LastName);
        Assert.Equal("Alpha", model[1].LastName);
    }

    [Fact]
    public void Index_SortByDate_ReturnsByEnrollmentDateAscending()
    {
        CreateStudent("Alice", "A", new DateTime(2021, 1, 1));
        CreateStudent("Bob", "B", new DateTime(2019, 1, 1));

        var result = _controller.Index("Date", null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal("B", model[0].LastName);  // 2019 first
        Assert.Equal("A", model[1].LastName);  // 2021 second
    }

    [Fact]
    public void Index_SortByDateDesc_ReturnsByEnrollmentDateDescending()
    {
        CreateStudent("Alice", "A", new DateTime(2021, 1, 1));
        CreateStudent("Bob", "B", new DateTime(2019, 1, 1));

        var result = _controller.Index("date_desc", null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal("A", model[0].LastName);  // 2021 first
        Assert.Equal("B", model[1].LastName);  // 2019 second
    }

    [Fact]
    public void Index_DefaultSort_OrdersByLastNameAscending()
    {
        CreateStudent("Alice", "Zeta");
        CreateStudent("Bob", "Alpha");

        var result = _controller.Index(null, null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal("Alpha", model[0].LastName);
        Assert.Equal("Zeta", model[1].LastName);
    }

    [Fact]
    public void Index_WithSearchString_ResetsToPage1()
    {
        for (int i = 0; i < 15; i++)
            CreateStudent($"Name{i}", "TestLast");

        var result = _controller.Index(null, null, "TestLast", null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_NullSearchString_UsesCurrentFilter()
    {
        CreateStudent("Alice", "FilterName");
        CreateStudent("Bob", "Other");

        var result = _controller.Index(null, "FilterName", null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Single(model);
    }

    #endregion

    #region Details

    [Fact]
    public void Details_WithNullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_WithValidId_ReturnsViewWithStudent()
    {
        var student = CreateStudent();

        var result = _controller.Details(student.ID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Student>(viewResult.Model);
        Assert.Equal(student.ID, model.ID);
        Assert.Equal("Doe", model.LastName);
    }

    #endregion

    #region Create GET

    [Fact]
    public void Create_Get_ReturnsViewWithNewStudent()
    {
        var result = _controller.Create();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Student>(viewResult.Model);
        Assert.Equal(DateTime.Today, model.EnrollmentDate);
    }

    #endregion

    #region Create POST

    [Fact]
    public void Create_Post_ValidStudent_RedirectsToIndex()
    {
        var student = new Student
        {
            FirstMidName = "Jane",
            LastName = "Doe",
            EnrollmentDate = new DateTime(2020, 9, 1)
        };

        var result = _controller.Create(student);

        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);

        // Verify student was saved
        Assert.Single(_context.Students);
        var saved = _context.Students.First();
        Assert.Equal("Jane", saved.FirstMidName);
        Assert.Equal("Doe", saved.LastName);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student
        {
            FirstMidName = "Jane",
            EnrollmentDate = new DateTime(2020, 9, 1)
        };

        var result = _controller.Create(student);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.IsType<Student>(viewResult.Model);
    }

    [Fact]
    public void Create_Post_DefaultEnrollmentDate_AddsModelError()
    {
        var student = new Student
        {
            FirstMidName = "Jane",
            LastName = "Doe",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Create(student);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Create_Post_DateBelow1753_AddsModelError()
    {
        var student = new Student
        {
            FirstMidName = "Jane",
            LastName = "Doe",
            EnrollmentDate = new DateTime(1752, 12, 31)
        };

        var result = _controller.Create(student);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    #endregion

    #region Edit GET

    [Fact]
    public void Edit_Get_WithNullId_ReturnsBadRequest()
    {
        var result = _controller.Edit((int?)null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_WithInvalidId_ReturnsNotFound()
    {
        var result = _controller.Edit(999);
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_Get_WithValidId_ReturnsViewWithStudent()
    {
        var student = CreateStudent();

        var result = _controller.Edit(student.ID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Student>(viewResult.Model);
        Assert.Equal(student.ID, model.ID);
    }

    #endregion

    #region Edit POST

    [Fact]
    public void Edit_Post_ValidStudent_RedirectsToIndex()
    {
        var student = CreateStudent();
        // Detach so we can simulate a form post
        _context.Entry(student).State = EntityState.Detached;

        var editedStudent = new Student
        {
            ID = student.ID,
            FirstMidName = "Updated",
            LastName = "Name",
            EnrollmentDate = new DateTime(2021, 1, 1)
        };

        var result = _controller.Edit(editedStudent);

        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
    }

    [Fact]
    public void Edit_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student
        {
            ID = 1,
            EnrollmentDate = new DateTime(2020, 9, 1)
        };

        var result = _controller.Edit(student);

        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void Edit_Post_DefaultEnrollmentDate_AddsModelError()
    {
        var student = new Student
        {
            ID = 1,
            FirstMidName = "Jane",
            LastName = "Doe",
            EnrollmentDate = default(DateTime)
        };

        var result = _controller.Edit(student);

        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    #endregion

    #region Delete GET

    [Fact]
    public void Delete_Get_WithNullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_WithInvalidId_ReturnsNotFound()
    {
        var result = _controller.Delete(999);
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Delete_Get_WithValidId_ReturnsViewWithStudent()
    {
        var student = CreateStudent();

        var result = _controller.Delete(student.ID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Student>(viewResult.Model);
        Assert.Equal(student.ID, model.ID);
    }

    #endregion

    #region DeleteConfirmed POST

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesStudentAndRedirects()
    {
        var student = CreateStudent();

        var result = _controller.DeleteConfirmed(student.ID);

        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
        Assert.Empty(_context.Students);
    }

    #endregion
}

