            LastName = "User",
            EnrollmentDate = new DateTime(2020, 9, 1)
        };

        _context.Students.Add(student);
        _context.SaveChanges();

        var retrieved = _context.Students.First();
        Assert.Equal("Test", retrieved.FirstMidName);
        Assert.Equal("User", retrieved.LastName);
        Assert.Equal(new DateTime(2020, 9, 1), retrieved.EnrollmentDate);
    }

    [Fact]
    public void CanAddAndRetrieveCourse()
    {
        var dept = new Department
        {
            Name = "Science",
            Budget = 100000m,
            StartDate = new DateTime(2020, 1, 1)
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course
        {
            CourseID = 1001,
            Title = "Physics",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var retrieved = _context.Courses.Include(c => c.Department).First();
        Assert.Equal("Physics", retrieved.Title);
        Assert.Equal(3, retrieved.Credits);
        Assert.Equal("Science", retrieved.Department.Name);
    }

