        Assert.True(withGrades > 0);

        // At least one enrollment should not have a grade (Arturo Anand's Chemistry)
        var withoutGrades = _context.Enrollments.Count(e => e.Grade == null);
        Assert.True(withoutGrades > 0);
    }

    [Fact]
    public void Initialize_DepartmentsHaveAdministrators()
    {
        DbInitializer.Initialize(_context);

        var deptsWithAdmin = _context.Departments.Count(d => d.InstructorID != null);
        Assert.Equal(4, deptsWithAdmin);
    }
}

