using ContosoUniversity.Services;
using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut;

    public NotificationServiceTests()
    {
        _sut = new NotificationService();
        // Drain any notifications left from other tests (shared static queue)
        while (_sut.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        // Drain the queue after each test
        while (_sut.ReceiveNotification() != null) { }
        _sut.Dispose();
    }

    /// <summary>
    /// Helper: Sends a notification with a unique entityId, then drains the queue
    /// until the matching notification is found. This avoids flakiness from the
    /// shared static ConcurrentQueue when other tests (e.g., controller tests)
    /// may also enqueue notifications.
    /// </summary>
    private Notification SendAndReceive(string entityType, string entityId, string? displayName, EntityOperation operation, string? userName = null)
    {
        if (displayName != null)
            _sut.SendNotification(entityType, entityId, displayName, operation, userName);
        else
            _sut.SendNotification(entityType, entityId, operation, userName);

        // Drain until we find our specific notification
        Notification? found = null;
        int maxAttempts = 100;
        while (maxAttempts-- > 0)
        {
            var n = _sut.ReceiveNotification();
            if (n == null) break;
            if (n.EntityType == entityType && n.EntityId == entityId)
            {
                found = n;
                break;
            }
        }
        return found!;
    }

    [Fact]
    public void SendNotification_WithDisplayName_EnqueuesNotificationWithCorrectMessage()
    {
        // Act
        var notification = SendAndReceive("Student", "snd_1", "John Smith", EntityOperation.CREATE, "admin");

        // Assert
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("snd_1", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Contains("John Smith", notification.Message);
        Assert.Contains("created", notification.Message);
        Assert.Equal("admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesIdInMessage()
    {
        var notification = SendAndReceive("Course", "snd_2", null, EntityOperation.UPDATE);

        Assert.NotNull(notification);
        Assert.Contains("ID: snd_2", notification.Message);
        Assert.Contains("updated", notification.Message);
    }

    [Fact]
    public void SendNotification_WithoutUserName_DefaultsToSystem()
    {
        var notification = SendAndReceive("Student", "snd_3", null, EntityOperation.CREATE);

        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_WithUserName_SetsCreatedBy()
    {
        var notification = SendAndReceive("Student", "snd_4", "Test Student", EntityOperation.CREATE, "testUser");

        Assert.NotNull(notification);
        Assert.Equal("testUser", notification.CreatedBy);
    }

    [Theory]
    [InlineData(EntityOperation.CREATE, "created")]
    [InlineData(EntityOperation.UPDATE, "updated")]
    [InlineData(EntityOperation.DELETE, "deleted")]
    public void SendNotification_DifferentOperations_GeneratesCorrectMessage(EntityOperation operation, string expectedVerb)
    {
        var id = $"snd_op_{operation}";
        var notification = SendAndReceive("Department", id, "Engineering", operation, "user1");

        Assert.NotNull(notification);
        Assert.Equal(operation.ToString(), notification.Operation);
        Assert.Contains(expectedVerb, notification.Message);
        Assert.Contains("Engineering", notification.Message);
    }

    [Fact]
    public void ReceiveNotification_WhenQueueEmpty_ReturnsNull()
    {
        // Drain everything first
        while (_sut.ReceiveNotification() != null) { }

        var result = _sut.ReceiveNotification();
        Assert.Null(result);
    }

    [Fact]
    public void SendAndReceive_MultipleNotifications_ReturnsInFIFOOrder()
    {
        // Drain first
        while (_sut.ReceiveNotification() != null) { }

        // Arrange - use unique identifiers
        _sut.SendNotification("StudentFIFO", "fifo_1", EntityOperation.CREATE);
        _sut.SendNotification("CourseFIFO", "fifo_2", EntityOperation.UPDATE);
        _sut.SendNotification("DepartmentFIFO", "fifo_3", EntityOperation.DELETE);

        // Act & Assert - find our notifications in order
        Notification? first = null, second = null, third = null;
        int maxAttempts = 50;
        while (maxAttempts-- > 0)
        {
            var n = _sut.ReceiveNotification();
            if (n == null) break;
            if (n.EntityId == "fifo_1") first = n;
            else if (n.EntityId == "fifo_2") second = n;
            else if (n.EntityId == "fifo_3") third = n;
            if (first != null && second != null && third != null) break;
        }

        Assert.NotNull(first);
        Assert.Equal("StudentFIFO", first.EntityType);
        Assert.NotNull(second);
        Assert.Equal("CourseFIFO", second.EntityType);
        Assert.NotNull(third);
        Assert.Equal("DepartmentFIFO", third.EntityType);
    }

    [Fact]
    public void SendNotification_CreatedAt_IsRecentTimestamp()
    {
        var before = DateTime.Now.AddSeconds(-1);

        var notification = SendAndReceive("Student", "snd_ts", null, EntityOperation.CREATE);

        Assert.NotNull(notification);
        Assert.True(notification.CreatedAt >= before);
        Assert.True(notification.CreatedAt <= DateTime.Now.AddSeconds(1));
    }

    [Fact]
    public void SendNotification_WithWhitespaceDisplayName_UsesIdFallback()
    {
        var notification = SendAndReceive("Student", "snd_ws", "   ", EntityOperation.CREATE, "user");

        Assert.NotNull(notification);
        Assert.Contains("ID: snd_ws", notification.Message);
    }

    [Fact]
    public void SendNotification_WithEmptyDisplayName_UsesIdFallback()
    {
        var notification = SendAndReceive("Student", "snd_empty", "", EntityOperation.CREATE, "user");

        Assert.NotNull(notification);
        Assert.Contains("ID: snd_empty", notification.Message);
    }

    [Fact]
    public void SendNotification_WithNullDisplayName_UsesIdFallback()
    {
        _sut.SendNotification("Student", "snd_null", null, EntityOperation.CREATE, "user");

        // Find our notification
        Notification? found = null;
        int maxAttempts = 50;
        while (maxAttempts-- > 0)
        {
            var n = _sut.ReceiveNotification();
            if (n == null) break;
            if (n.EntityId == "snd_null") { found = n; break; }
        }

        Assert.NotNull(found);
        Assert.Contains("ID: snd_null", found.Message);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        var exception = Record.Exception(() => _sut.MarkAsRead(1));
        Assert.Null(exception);
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var service = new NotificationService();
        var exception = Record.Exception(() => service.Dispose());
        Assert.Null(exception);
    }

    [Fact]
    public void SendNotification_IsRead_DefaultsFalse()
    {
        var notification = SendAndReceive("Student", "snd_read", "Test", EntityOperation.CREATE, "admin");

        Assert.NotNull(notification);
        Assert.False(notification.IsRead);
    }
}

